use xiom.io;

type Inventory = {
  count: Int;
  invariant: count >= 0;
}

fn sell(item: &mut Inventory, qty: Int)
  requires: qty > 0;
  requires: qty <= item.count;
  ensures: item.count == item@pre.count - qty;
{
  item.count = item.count - qty;
}

fn restock(item: &mut Inventory, qty: Int)
  requires: qty > 0;
  ensures: item.count == item@pre.count + qty;
{
  item.count = item.count + qty;
}

fn main() -> Int {
  var inv: Inventory = Inventory{ count: 100 };
  sell(&mut inv, 20);
  restock(&mut inv, 50);
  return inv.count;
}
